{"version":3,"file":"app.jsdbx","sources":["../../src/client/components/HeroHeader.tsx","../../src/client/app.css","../../src/client/components/HeroHeader.css","../../src/client/components/ImpactStrip.css","../../src/client/components/ImpactStrip.tsx","../../src/client/components/PulseScoreHero.css","../../src/client/components/PulseScoreHero.tsx","../../src/client/components/KpiCards.css","../../src/client/components/KpiCards.tsx","../../src/client/components/NetworkHealth.tsx","../../src/client/components/NetworkHealth.css","../../src/client/components/CriticalAlerts.css","../../src/client/components/CriticalAlerts.tsx","../../src/client/components/AiPanel.css","../../src/client/components/AiPanel.tsx","../../src/client/components/StoreHealth.css","../../src/client/components/StoreHealth.tsx","../../src/client/components/LiveTimeline.css","../../src/client/components/LiveTimeline.tsx","../../src/client/components/CityHeatmap.css","../../src/client/components/CityHeatmap.tsx","../../src/client/components/TrendChart.css","../../src/client/components/TrendChart.tsx","../../src/client/app.tsx"],"sourcesContent":["import React, { useState, useEffect } from 'react';
import './HeroHeader.css';

export function HeroHeader() {
  const [time, setTime] = useState(new Date());
  const [notifications] = useState(5);
  const [refreshCountdown, setRefreshCountdown] = useState(30);

  // Real clock - updates every second
  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Auto-refresh countdown every 30 seconds
  useEffect(() => {
    const timer = setInterval(() => {
      setRefreshCountdown((c) => {
        if (c <= 1) return 30;
        return c - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const timeStr = time.toLocaleTimeString('en-IN', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true,
  });

  return (
    <header className="hero-header">
      <div className="hero-header__left">
        <div className="hero-header__brand">
          <span className="hero-header__logo">◆</span>
          <div>
            <h1 className="hero-header__title">Quick Commerce Operations Command Center</h1>
            <p className="hero-header__subtitle">Real-Time Operational Intelligence • Hyderabad Region</p>
          </div>
        </div>
      </div>
      <div className="hero-header__right">
        <div className="hero-header__notification" title={`${notifications} unread alerts`}>
          <span className="hero-header__bell">🔔</span>
          <span className="hero-header__notif-badge">{notifications}</span>
        </div>
        <div className="hero-header__live-badge">
          <span className="hero-header__live-dot" />
          <span className="hero-header__live-text">LIVE</span>
        </div>
        <div className="hero-header__meta">
          <div className="hero-header__meta-item">
            <span className="hero-header__meta-label">Current Time</span>
            <span className="hero-header__meta-value">{timeStr}</span>
          </div>
          <div className="hero-header__divider" />
          <div className="hero-header__meta-item">
            <span className="hero-header__meta-label">Auto-Refresh</span>
            <span className="hero-header__meta-value">
              <span className={`hero-header__refresh-indicator ${refreshCountdown <= 3 ? 'hero-header__refresh-indicator--active' : ''}`}>◉</span>
              {' '}{refreshCountdown}s
            </span>
          </div>
          <div className="hero-header__divider" />
          <div className="hero-header__meta-item">
            <span className="hero-header__meta-label">Stores Online</span>
            <span className="hero-header__meta-value hero-header__meta-value--green">192 / 200</span>
          </div>
        </div>
      </div>
      <div className="hero-header__border" />
    </header>
  );
}
",":root {
  --cc-bg-primary: #0a0e1a;
  --cc-bg-card: #131a2e;
  --cc-border: #1e2a45;
  --cc-accent: #00c896;
  --cc-accent-glow: rgba(0, 200, 150, 0.1);
  --cc-warning: #f59e0b;
  --cc-critical: #ef4444;
  --cc-text-primary: #e2e8f0;
  --cc-text-secondary: #94a3b8;
  --cc-radius: 14px;
  --cc-spacing: 24px;
  --cc-blue: #3b82f6;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--cc-bg-primary);
  color: var(--cc-text-primary);
  font-family: system-ui, -apple-system, sans-serif;
  scroll-behavior: smooth;
  overflow-y: auto;
  min-height: 100vh;
}

#root {
  min-height: 100vh;
}

.command-center {
  max-width: 1600px;
  margin: 0 auto;
  padding: var(--cc-spacing);
  display: grid;
  gap: var(--cc-spacing);
}

.command-center__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--cc-spacing);
}

.card {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  padding: var(--cc-spacing);
}

.card--glow {
  box-shadow: 0 0 20px var(--cc-accent-glow), inset 0 1px 0 rgba(255,255,255,0.03);
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--cc-text-secondary);
  text-transform: uppercase;
  margin-bottom: 16px;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.3); }
}
