","import React from 'react';
import './ImpactStrip.css';

const impacts = [
  { value: '₹2.4L', label: 'Fraud Prevented', icon: '🛡' },
  { value: '184', label: 'Auto Resolutions', icon: '⚡' },
  { value: '42', label: 'SLA Breaches Avoided', icon: '◎' },
  { value: '18', label: 'Technician Dispatches', icon: '🔧' },
  { value: '96%', label: 'Customer Satisfaction', icon: '⭐' },
];

export function ImpactStrip() {
  return (
    <div className="impact-strip">
      <div className="impact-strip__label">TODAY'S BUSINESS IMPACT</div>
      <div className="impact-strip__items">
        {impacts.map((item, idx) => (
          <React.Fragment key={item.label}>
            <div className="impact-strip__item">
              <span className="impact-strip__icon">{item.icon}</span>
              <span className="impact-strip__value">{item.value}</span>
              <span className="impact-strip__name">{item.label}</span>
            </div>
            {idx < impacts.length - 1 && <span className="impact-strip__divider">|</span>}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}
