","import React, { useState, useEffect } from 'react';
import './KpiCards.css';

interface KpiData {
  label: string;
  value: string;
  icon: string;
  color: string;
  trend: string;
  trendDir: 'up' | 'down';
  sparkline: number[];
}

const kpis: KpiData[] = [
  { label: 'Auto Resolution', value: '84%', icon: '⚡', color: 'var(--cc-accent)', trend: '↑ 12%', trendDir: 'up', sparkline: [3, 4, 5, 4, 6, 7, 8] },
  { label: 'Critical Stores', value: '3', icon: '🔴', color: 'var(--cc-critical)', trend: '↓ 2', trendDir: 'down', sparkline: [7, 6, 5, 5, 4, 4, 3] },
  { label: 'Fraud Prevented', value: '₹2.4L', icon: '🛡', color: 'var(--cc-blue)', trend: '↑ ₹18K', trendDir: 'up', sparkline: [2, 3, 2, 4, 5, 4, 6] },
  { label: 'Orders Today', value: '152K', icon: '📦', color: 'var(--cc-accent)', trend: '↑ 8%', trendDir: 'up', sparkline: [4, 5, 4, 6, 5, 7, 8] },
  { label: 'SLA Compliance', value: '96%', icon: '◎', color: 'var(--cc-accent)', trend: '↑ 2%', trendDir: 'up', sparkline: [5, 5, 6, 6, 7, 7, 8] },
];

function Sparkline({ data, color }: { data: number[]; color: string }) {
  const max = Math.max(...data);
  return (
    <div className="kpi-sparkline">
      {data.map((v, i) => (
        <div
          key={i}
          className="kpi-sparkline__bar"
          style={{ height: `${(v / max) * 100}%`, background: color, opacity: 0.4 + (i / data.length) * 0.6 }}
        />
      ))}
    </div>
  );
}

export function KpiCards() {
  const [elapsed, setElapsed] = useState(2);

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsed((e) => (e >= 10 ? 1 : e + 1));
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="kpi-cards">
      {kpis.map((kpi) => (
        <div key={kpi.label} className="kpi-cards__item card card--glow" style={{ borderLeftColor: kpi.color }}>
          <div className="kpi-cards__live-indicator">
            <span className="kpi-cards__live-dot" />
            <span className="kpi-cards__live-text">LIVE · {elapsed}s ago</span>
          </div>
          <div className="kpi-cards__top">
            <span className="kpi-cards__icon" style={{ color: kpi.color }}>{kpi.icon}</span>
            <Sparkline data={kpi.sparkline} color={kpi.color} />
          </div>
          <div className="kpi-cards__value">{kpi.value}</div>
          <div className="kpi-cards__bottom">
            <span className="kpi-cards__label">{kpi.label}</span>
            <span className={`kpi-cards__trend kpi-cards__trend--${kpi.trendDir}`}>{kpi.trend}</span>
          </div>
        </div>
      ))}
    </div>
  );
}
","import React, { useState, useEffect } from 'react';
import './NetworkHealth.css';

export function NetworkHealth() {
  const [activeStores, setActiveStores] = useState(192);
  const totalStores = 200;

  useEffect(() => {
    const interval = setInterval(() => {
      setActiveStores((s) => {
        const delta = Math.random() > 0.7 ? -1 : Math.random() > 0.5 ? 1 : 0;
        return Math.max(185, Math.min(200, s + delta));
      });
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const percentage = Math.round((activeStores / totalStores) * 100);
  const circumference = 2 * Math.PI * 80;
  const dashArray = `${(percentage / 100) * circumference}, ${circumference}`;

  return (
    <div className="network-health card">
      <div className="network-health__content">
        <div className="network-health__gauge">
          <svg viewBox="0 0 200 200" className="network-health__svg">
            <circle cx="100" cy="100" r="80" className="network-health__ring-bg" />
            <circle cx="100" cy="100" r="80" className="network-health__ring-fill"
              strokeDasharray={dashArray} />
            <circle cx="100" cy="100" r="65" className="network-health__ring-inner" />
          </svg>
          <div className="network-health__gauge-center">
            <span className="network-health__gauge-percent">{percentage}%</span>
            <span className="network-health__gauge-label">UPTIME</span>
          </div>
          <div className="network-health__pulse-ring" />
        </div>
        <div className="network-health__info">
          <div className="network-health__title-row">
            <span className="network-health__section-label">NETWORK STATUS</span>
            <span className="network-health__live-badge">● LIVE</span>
          </div>
          <div className="network-health__status-row">
            <span className="network-health__status-dot" />
            <span className="network-health__status-text">HEALTHY</span>
          </div>
          <div className="network-health__detail">Store Network Operational</div>
          <div className="network-health__bar-section">
            <div className="network-health__bar-label">
              <span>{activeStores}/{totalStores} Active</span>
              <span className="network-health__bar-percent">{percentage}%</span>
            </div>
            <div className="network-health__bar-track">
              <div className="network-health__bar-fill" style={{ width: `${percentage}%` }} />
            </div>
          </div>
          <div className="network-health__stats">
            <div className="network-health__stat">
              <span className="network-health__stat-value">{activeStores}</span>
              <span className="network-health__stat-label">Active</span>
            </div>
            <div className="network-health__stat">
              <span className="network-health__stat-value network-health__stat-value--warning">{totalStores - activeStores}</span>
              <span className="network-health__stat-label">Offline</span>
            </div>
            <div className="network-health__stat">
              <span className="network-health__stat-value">99.6%</span>
              <span className="network-health__stat-label">Uptime MTD</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
