  store: string;
  area: string;
  issue: string;
  time: string;
}

const alerts: Alert[] = [
  { severity: 'critical', severityLabel: 'CRITICAL', store: 'Store 112', area: 'Banjara Hills', issue: 'Freezer Failure — Unit #3 Temperature 18°C', time: '2 mins ago' },
  { severity: 'high', severityLabel: 'HIGH', store: 'Store 45', area: 'Madhapur', issue: 'Refund Spike (+340%) — ₹42K in 30 min', time: '6 mins ago' },
  { severity: 'medium', severityLabel: 'MEDIUM', store: 'Store 81', area: 'Gachibowli', issue: 'Inventory Shortage — 12 SKUs below threshold', time: '12 mins ago' },
  { severity: 'critical', severityLabel: 'CRITICAL', store: 'Store 23', area: 'Kondapur', issue: 'PulseScore Critical (28) — Auto-escalated', time: '15 mins ago' },
  { severity: 'medium', severityLabel: 'MEDIUM', store: 'Store 67', area: 'Jubilee Hills', issue: 'Delivery Delays — Avg 22 min over SLA', time: '18 mins ago' },
];

export function CriticalAlerts() {
  return (
    <div className="card critical-alerts">
      <div className="critical-alerts__header">
        <h2 className="section-title">Critical Alerts</h2>
        <span className="critical-alerts__count">{alerts.length} Active</span>
      </div>
      <div className="critical-alerts__list">
        {alerts.map((a, i) => (
          <div key={i} className={`critical-alerts__item critical-alerts__item--${a.severity}`}>
            <div className="critical-alerts__left">
              <span className={`critical-alerts__badge critical-alerts__badge--${a.severity}`}>
                {a.severityLabel}
              </span>
              <div className="critical-alerts__body">
                <div className="critical-alerts__store-row">
                  <span className="critical-alerts__store">{a.store}</span>
                  <span className="critical-alerts__area">{a.area}</span>
                </div>
                <div className="critical-alerts__issue">{a.issue}</div>
              </div>
            </div>
            <span className="critical-alerts__time">{a.time}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
