          <div className="ai-panel__metric">
            <span className="ai-panel__metric-value ai-panel__metric-value--green">₹18,000</span>
            <span className="ai-panel__metric-label">Estimated Save</span>
          </div>
          <div className="ai-panel__metric">
            <span className="ai-panel__metric-value ai-panel__metric-value--blue">12 min</span>
            <span className="ai-panel__metric-label">Est. Resolution</span>
          </div>
        </div>

        <div className="ai-panel__business-impact">
          <div className="ai-panel__impact-title">BUSINESS IMPACT</div>
          <div className="ai-panel__impact-items">
            {businessImpact.map((item) => (
              <div key={item.label} className="ai-panel__impact-item">
                <span className="ai-panel__impact-check" style={{ color: item.color }}>{item.icon}</span>
                <span className="ai-panel__impact-label">{item.label}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="ai-panel__actions-label">Suggested Actions</div>
        <div className="ai-panel__actions">
          {actions.map((a) => (
            <div key={a.label} className={`ai-panel__action-item ai-panel__action-item--${a.status}`}>
              <span className="ai-panel__action-icon">{a.icon}</span>
              <span className="ai-panel__action-text">{a.label}</span>
              <span className={`ai-panel__action-status ai-panel__action-status--${a.status}`}>
                {a.status === 'done' ? '✓' : a.status === 'in-progress' ? '◌' : '○'}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
