","import React from 'react';
import './TrendChart.css';

interface DayData {
  day: string;
  value: number;
  annotation?: string;
}

const days: DayData[] = [
  { day: 'Mon', value: 42 },
  { day: 'Tue', value: 38 },
  { day: 'Wed', value: 55 },
  { day: 'Thu', value: 61 },
  { day: 'Fri', value: 48, annotation: 'Marketing Campaign → ↑ Orders' },
  { day: 'Sat', value: 72, annotation: 'Freezer Failure → ↑ Complaints' },
  { day: 'Sun', value: 35 },
];

const maxVal = Math.max(...days.map((d) => d.value));

export function TrendChart() {
  return (
    <div className="card trend-chart">
      <h2 className="section-title">Complaint Trends — Last 7 Days</h2>
      <div className="trend-chart__bars">
        {days.map((d) => (
          <div key={d.day} className="trend-chart__col">
            {d.annotation && (
              <div className="trend-chart__annotation">
                <span className="trend-chart__annotation-text">{d.annotation}</span>
                <span className="trend-chart__annotation-arrow">▼</span>
              </div>
            )}
            <span className="trend-chart__value">{d.value}</span>
            <div className="trend-chart__bar-wrap">
              <div
                className={`trend-chart__bar ${d.value === maxVal ? 'trend-chart__bar--peak' : ''}`}
                style={{ height: `${(d.value / maxVal) * 100}%` }}
              />
            </div>
            <span className="trend-chart__label">{d.day}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
